# Paso 4: instalar la lista de permisos (default.rules).
ruta_permisos_copia = None
mensaje_permisos = ""
if not os.path.isfile(ruta_permisos_fuente):
    mensaje_permisos = (
        "La lista de permisos del proyecto no existe en "
        + ruta_permisos_fuente + ", asi que no se instalo. No se "
        "inventa nada."
    )
else:
    try:
        contenido_permisos = _leer_texto(ruta_permisos_fuente)
    except OSError as error:
        mensaje_permisos = (
            "No se pudo leer la lista de permisos del proyecto en "
            + ruta_permisos_fuente + ". Motivo: " + str(error)
        )
    else:
        try:
            if not os.path.isdir(carpeta_rules):
                os.makedirs(carpeta_rules, exist_ok=True)
            if os.path.isfile(ruta_permisos_destino):
                if not os.path.isdir(carpeta_rescate):
                    os.makedirs(carpeta_rescate, exist_ok=True)
                nombre_copia_permisos = _nombre_copia_con_fecha(
                    NOMBRE_PERMISOS_DESTINO
                )
                ruta_permisos_copia = os.path.join(
                    carpeta_rescate, nombre_copia_permisos
                )
                shutil.copyfile(
                    ruta_permisos_destino, ruta_permisos_copia
                )
            _escribir_texto(ruta_permisos_destino, contenido_permisos)
            mensaje_permisos = (
                "La lista de permisos quedo instalada. Se copio de: "
                + ruta_permisos_fuente + " Se copio a: "
                + ruta_permisos_destino
            )
            if ruta_permisos_copia is not None:
                mensaje_permisos += (
                    " Antes de pisarla se guardo una copia de lo que "
                    "habia en: " + ruta_permisos_copia
                )
            else:
                mensaje_permisos += (
                    " No habia nada antes en el destino, asi que no "
                    "hubo copia de seguridad que guardar."
                )
        except OSError as error:
            mensaje_permisos = (
                "No se pudo instalar la lista de permisos en "
                + ruta_permisos_destino + ". Motivo: " + str(error)
            )

# Paso 5: armar el resumen en palabras simples.
partes = []
partes.append("Listo. Las reglas de Codex quedaron instaladas.")
partes.append("Se copio de: " + ruta_fuente)
partes.append("Se copio a: " + ruta_destino)
if ruta_copia is not None:
    partes.append(
        "Antes de pisarlo se guardo una copia de lo que habia en: "
        + ruta_copia
    )
else:
    partes.append(
        "No habia nada antes en el destino, asi que no hubo copia de "
        "seguridad que guardar."
    )
partes.append(mensaje_permisos)
partes.append(
    "Codex ya puede leer las reglas nuevas, incluido el apartado de que "
    "no espera nunca."
)

return {
    "ok": True,
    "mensaje": " ".join(partes),
    "fuente": ruta_fuente,
    "destino": ruta_destino,
    "copia": ruta_copia,
    "fuente_permisos": ruta_permisos_fuente,
    "destino_permisos": ruta_permisos_destino,
    "copia_permisos": ruta_permisos_copia,
}

